import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BDCokyix.js";const m=JSON.parse('{"title":"UI Revamp v0 — @soma/ui Scaffolding Plan","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/prd/ui-revamp-v0-scaffold.md","filePath":"architecture/prd/ui-revamp-v0-scaffold.md","lastUpdated":1780254295000}'),r={name:"architecture/prd/ui-revamp-v0-scaffold.md"};function s(n,e,i,c,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="ui-revamp-v0-—-soma-ui-scaffolding-plan" tabindex="-1">UI Revamp v0 — <code>@soma/ui</code> Scaffolding Plan <a class="header-anchor" href="#ui-revamp-v0-—-soma-ui-scaffolding-plan" aria-label="Permalink to &quot;UI Revamp v0 — `@soma/ui` Scaffolding Plan&quot;">​</a></h1><p>Companion to <a href="./ui-revamp-v0">ui-revamp-v0.md</a> (PRD), the seven refs docs in this folder, and <a href="./../adrs/0005-ui-revamp-v0">ADR-0005</a>. This doc turns the PRD §6 component table into a sequenced, dependency-aware build plan: which components are new vs. refactors of existing code, what depends on what, the order in which they ship to <code>@soma/ui</code>, and the criteria a component must meet before any <code>desktop/soma</code> consumer wires it in.</p><p>PRD §7 step 5 is the deliverable; this is the spec for how step 5 runs.</p><h2 id="_1-pre-flight-the-token-sweep" tabindex="-1">1. Pre-flight: the token sweep <a class="header-anchor" href="#_1-pre-flight-the-token-sweep" aria-label="Permalink to &quot;1. Pre-flight: the token sweep&quot;">​</a></h2><p>Before any component work, the design token system from <a href="./../adrs/0005-ui-revamp-v0">ADR-0005 §7</a> and <a href="./ui-revamp-v0-refs-files-density">refs §3</a> lands in <a href="../../../../desktop/desktop-ui/src/styles.css">desktop/desktop-ui/src/styles.css</a>. Concretely:</p><ul><li><strong>Font sizes (Tailwind-native).</strong> Use <code>text-sm</code> (14px) for body + dense UI rows and <code>text-xs</code> (12px) for caps / hint text. Earlier waves shipped custom <code>--text-body / --text-ui-sm / --text-ui-xs</code> tokens at exact 14 / 13 / 11px from a density audit, but they were removed when tailwind-merge was found to silently drop them when combined with <code>text-{color}</code> classes in <code>cn(...)</code> compositions. The 1px upward adjustment on the densest rows is accepted as a tradeoff for the simpler scale.</li><li><strong>Line-heights.</strong> <code>--leading-body: 1.5</code>, <code>--leading-ui: 1.2</code>. (Bumped from PRD&#39;s original 1.45.)</li><li><strong>Row heights.</strong> Utility classes for three tiers, sized by content: <ul><li><code>row-text</code> — <strong>2rem (32px)</strong>, for text-only or icon-leading rows. <strong>Does not fit a 40px avatar</strong> — use <code>row-avatar</code> instead.</li><li><code>row-avatar</code> — <strong>2.5rem (40px)</strong>, for rows with avatars / file-type glyphs (mention rows, attachments, members, bots). Matches <code>DenseRow</code>&#39;s existing <code>h-10</code> leading slot.</li><li><code>row-card</code> — <strong>3.25rem (52px)</strong>, for rows with two-line content (primary + sub).</li></ul></li><li><strong>Border + shadow.</strong> Establish exactly one shadow token (<code>--shadow-elevated</code>), used by modal + popup only. The existing <code>surface-card</code> / <code>glass-panel</code> utilities stay reachable as <code>surface-card-legacy</code> / <code>glass-panel-legacy</code> so non-revamped screens keep their depth during the incremental cutover. New revamped surfaces use the simple names (<code>surface-card</code>, <code>glass-panel</code>) backed by border-only / single-shadow-token rules. Once every screen is on revamped components (<a href="#5-cutover-order-into-desktopsoma">cutover §5</a> complete), the <code>-legacy</code> utilities get deleted in a sweep PR.</li><li><strong>DaisyUI theme.</strong> Audit <code>cmyk</code> (default) and <code>luxury</code> for shadow + radius. The default theme should ship with shadow disabled at the component level.</li></ul><p>Token sweep is the only PR that needs zero new components — it cleans the foundation so every wave that follows compiles into a consistent visual system without breaking non-revamped screens mid-cutover.</p><h2 id="_2-mapping-prd-§6-to-current-soma-ui-reality" tabindex="-1">2. Mapping PRD §6 to current <code>@soma/ui</code> reality <a class="header-anchor" href="#_2-mapping-prd-§6-to-current-soma-ui-reality" aria-label="Permalink to &quot;2. Mapping PRD §6 to current `@soma/ui` reality&quot;">​</a></h2><p>PRD §6 lists 20 components for v0. Many already exist in <code>desktop/desktop-ui/src/components/</code> as starting points. The scaffold work is: refactor where there is precedent, build where there is none.</p><p><strong>Audit override.</strong> A Storybook reality-check (<a href="./ui-revamp-v0-audit">ui-revamp-v0-audit.md</a>) walked every existing story and found that several &quot;refactor target&quot; components are actually unverified (no story) or visibly broken; some of the verdicts below are downgraded to rebuild or story-first-refactor. Read the audit alongside this table.</p><table tabindex="0"><thead><tr><th>PRD §6 component</th><th>Existing in <code>@soma/ui</code></th><th>Plan</th></tr></thead><tbody><tr><td><code>PanelContainer</code></td><td><em>none</em></td><td>New. <code>panels/panel-container.tsx</code>.</td></tr><tr><td><code>Panel</code></td><td><em>none</em></td><td>New. <code>panels/panel.tsx</code>.</td></tr><tr><td><code>SlashMenu</code></td><td><em>none</em> (closest precedent is <a href="./../../../../desktop/desktop-ui/src/components/overlays/command-palette.tsx"><code>overlays/command-palette.tsx</code></a>)</td><td>New. <code>editor/slash-menu.tsx</code>.</td></tr><tr><td><code>MentionPicker</code></td><td><em>none</em></td><td>New. <code>editor/mention-picker.tsx</code>.</td></tr><tr><td><code>SelectionBubble</code></td><td><a href="./../../../../desktop/desktop-ui/src/components/overlays/bubble-toolbar.tsx"><code>overlays/bubble-toolbar.tsx</code></a> (65 lines)</td><td><strong>Refactor.</strong> Replace internals; rename to <code>editor/selection-bubble.tsx</code>.</td></tr><tr><td><code>BotList</code></td><td><em>none</em> (closest: <a href="./../../../../desktop/desktop-ui/src/components/lists/roster-item.tsx"><code>lists/roster-item.tsx</code></a>)</td><td>New. <code>lists/bot-list.tsx</code>. Built on <code>DenseRow</code>.</td></tr><tr><td><code>CapabilityForm</code></td><td><em>none</em></td><td>New. <code>forms/capability-form.tsx</code>.</td></tr><tr><td><code>BackendSwitcher</code></td><td><a href="./../../../../desktop/desktop-ui/src/components/forms/ai-model-selector.tsx"><code>forms/ai-model-selector.tsx</code></a> (107 lines)</td><td><strong>Refactor.</strong> Move to <code>chat/backend-switcher.tsx</code>; reshape into a composer-footer chip per <a href="./ui-revamp-v0-refs">refs main §5</a>.</td></tr><tr><td><code>PeerAddressInput</code></td><td><em>none</em></td><td>New. <code>forms/peer-address-input.tsx</code>.</td></tr><tr><td><code>SpacesRail</code></td><td><em>none</em> explicit; layout shell in <code>layout/desktop-shell.tsx</code> may host one</td><td>New. <code>nav/spaces-rail.tsx</code>.</td></tr><tr><td><code>CharDisplay</code></td><td><a href="./../../../../desktop/desktop-ui/src/components/tapia/char-display.tsx"><code>tapia/char-display.tsx</code></a></td><td>Keep. Extract any inline shadows; verify density tokens.</td></tr><tr><td><code>DensityProvider</code></td><td><em>none</em></td><td>New. <code>primitives/density-provider.tsx</code>.</td></tr><tr><td><code>Empty</code></td><td><em>none</em></td><td>New. <code>primitives/empty.tsx</code> with <code>variant</code> prop (<code>full</code> / <code>compact</code> / <code>filter</code>).</td></tr><tr><td><code>DenseRow</code></td><td>partial in <code>lists/roster-item.tsx</code></td><td><strong>Refactor.</strong> Generalize roster-item&#39;s slot model into <code>lists/dense-row.tsx</code>.</td></tr><tr><td><code>CommandPalette</code></td><td><a href="./../../../../desktop/desktop-ui/src/components/overlays/command-palette.tsx"><code>overlays/command-palette.tsx</code></a> (166 lines)</td><td><strong>Refactor.</strong> Re-section per <a href="./ui-revamp-v0-refs-space-lifecycle">refs space-lifecycle §4.8</a>: Recent docs → Spaces → Documents → Commands.</td></tr><tr><td><code>TreePopover</code></td><td><em>none</em></td><td>New. <code>nav/tree-popover.tsx</code>. Built on <a href="https://www.npmjs.com/package/react-complex-tree" target="_blank" rel="noreferrer"><code>react-complex-tree</code></a> — installed in Wave 2 alongside this component.</td></tr><tr><td><code>PopupShell</code></td><td>precedent: <code>layout/window-chrome.tsx</code></td><td><strong>Refactor.</strong> Extract to <code>popup/popup-shell.tsx</code>; expose the 4-glyph cluster from <a href="./ui-revamp-v0-refs-popup-window">refs popup-window §6</a>.</td></tr><tr><td><code>SelectionAIBar</code></td><td><em>none</em></td><td>New. <code>editor/selection-ai-bar.tsx</code>.</td></tr><tr><td><code>InlineAIAcceptBar</code></td><td><em>none</em></td><td>New. <code>editor/inline-ai-accept-bar.tsx</code>.</td></tr><tr><td><code>NodeAIRegistry</code></td><td><em>none</em></td><td>New. <code>editor/node-ai-registry.ts</code> (logic, no UI).</td></tr><tr><td><code>InlineAIStream</code></td><td><em>none</em></td><td>New. <code>editor/inline-ai-stream.tsx</code>.</td></tr></tbody></table><h3 id="gaps-found-during-this-pass-—-proposed-additions" tabindex="-1">Gaps found during this pass — proposed additions <a class="header-anchor" href="#gaps-found-during-this-pass-—-proposed-additions" aria-label="Permalink to &quot;Gaps found during this pass — proposed additions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Why</th><th>File</th></tr></thead><tbody><tr><td><code>SettingsTabs</code></td><td>Locked by <a href="./ui-revamp-v0-refs-space-lifecycle">refs space-lifecycle §4.2</a> (horizontal pill/underline tabs) but missing from PRD §6. Reused by every settings page.</td><td><code>nav/settings-tabs.tsx</code></td></tr><tr><td><code>Pill</code></td><td>Status pills (bot pending/active/failed; default backend; capability scope counters) are everywhere. Tailwind-only is fine, but a typed primitive locks the variants and the color → semantic mapping.</td><td><code>primitives/pill.tsx</code></td></tr></tbody></table><p>These two should be added to PRD §6 in a small follow-up edit; for this scaffold plan I treat them as in-scope.</p><h2 id="_3-build-waves" tabindex="-1">3. Build waves <a class="header-anchor" href="#_3-build-waves" aria-label="Permalink to &quot;3. Build waves&quot;">​</a></h2><p>The waves below are dependency-ordered. Within a wave, components are independent and can be built in parallel.</p><h3 id="wave-0-—-foundation" tabindex="-1">Wave 0 — Foundation <a class="header-anchor" href="#wave-0-—-foundation" aria-label="Permalink to &quot;Wave 0 — Foundation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td>Token sweep (§1)</td><td>rem-based density tokens land in <code>styles.css</code>; revamped utilities use the simple names, legacy utilities (<code>surface-card-legacy</code>, <code>glass-panel-legacy</code>) preserve depth on non-revamped screens during cutover.</td></tr><tr><td>Storybook decorator fix</td><td>Drop the hardcoded <code>#0f172a</code> background; add <code>parameters.theme</code> knob for <code>cmyk</code> / <code>luxury</code> explicit testing; add a Storybook test-runner contrast assertion so dark-on-dark can&#39;t regress.</td></tr><tr><td><code>DensityProvider</code></td><td>React context exposing <code>density: &#39;dense&#39; | &#39;cozy&#39;</code>. v0 ships dense only; the provider exists so post-v0 cozy is a config flip.</td></tr><tr><td><strong>i18n harness</strong></td><td>Pick + wire one of <code>react-intl</code> / <code>i18next</code> (decision happens in this PR). Ships an English-only catalog; every new component in waves 1–3 routes user-facing strings through the harness (acceptance criterion §4.7). Cost-cheap insurance against a future locale retrofit.</td></tr><tr><td>Storybook conventions doc</td><td>Update <a href="./../../development/ui-components">docs/src/development/ui-components.md</a> with the story shape every component must follow (states matrix, hover/focus/disabled/empty/error, dark theme variant, i18n string usage).</td></tr></tbody></table><h3 id="wave-1-—-primitives-depend-only-on-wave-0" tabindex="-1">Wave 1 — Primitives (depend only on Wave 0) <a class="header-anchor" href="#wave-1-—-primitives-depend-only-on-wave-0" aria-label="Permalink to &quot;Wave 1 — Primitives (depend only on Wave 0)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Refs anchor</th></tr></thead><tbody><tr><td><code>Empty</code></td><td><a href="./ui-revamp-v0-refs-files-density">refs files-density §2</a></td></tr><tr><td><code>DenseRow</code> (refactor from <code>roster-item</code>)</td><td><a href="./ui-revamp-v0-refs-files-density">refs files-density §4</a></td></tr><tr><td><code>Pill</code> (new primitive)</td><td>Status patterns in <a href="./ui-revamp-v0-refs-assistant-bots">refs assistant-bots §3</a></td></tr><tr><td><code>PeerAddressInput</code></td><td><a href="./ui-revamp-v0-refs">refs main §4</a> step 1</td></tr><tr><td><code>CharDisplay</code> (extract inline styles)</td><td>already locked in <a href="./../../../../desktop/desktop-ui/src/components/tapia/char-display.tsx"><code>tapia/char-display.tsx</code></a></td></tr><tr><td><code>SpacesRail</code></td><td><a href="./ui-revamp-v0-refs-space-lifecycle">refs space-lifecycle §3</a></td></tr><tr><td><code>NodeAIRegistry</code> (types + in-memory impl)</td><td><a href="./ui-revamp-v0-refs-editor-ai">refs editor-ai §3</a>. Interface only — <code>editor/node-ai-registry.types.ts</code> + a trivial <code>createNodeAIRegistry()</code> Wave 2 can target. TipTap wiring lands in Wave 4.</td></tr></tbody></table><h3 id="wave-2-—-popovers-and-dropdowns-depend-on-wave-1" tabindex="-1">Wave 2 — Popovers and dropdowns (depend on Wave 1) <a class="header-anchor" href="#wave-2-—-popovers-and-dropdowns-depend-on-wave-1" aria-label="Permalink to &quot;Wave 2 — Popovers and dropdowns (depend on Wave 1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Refs anchor</th></tr></thead><tbody><tr><td><code>SlashMenu</code></td><td><a href="./ui-revamp-v0-refs-editor">refs editor §1</a> + ADR-0005 §11 amendment</td></tr><tr><td><code>SelectionBubble</code> (refactor from <code>bubble-toolbar</code>)</td><td><a href="./ui-revamp-v0-refs-editor">refs editor §2</a></td></tr><tr><td><code>MentionPicker</code></td><td><a href="./ui-revamp-v0-refs">refs main §3</a></td></tr><tr><td><code>BackendSwitcher</code> (refactor from <code>ai-model-selector</code>)</td><td><a href="./ui-revamp-v0-refs">refs main §5</a></td></tr><tr><td><code>TreePopover</code></td><td><a href="./ui-revamp-v0-refs-space-lifecycle">refs space-lifecycle §3</a></td></tr><tr><td><code>CommandPalette</code> (refactor existing)</td><td><a href="./ui-revamp-v0-refs-space-lifecycle">refs space-lifecycle §3</a></td></tr><tr><td><code>SettingsTabs</code></td><td><a href="./ui-revamp-v0-refs-space-lifecycle">refs space-lifecycle §2</a></td></tr><tr><td><code>SelectionAIBar</code></td><td><a href="./ui-revamp-v0-refs-editor-ai">refs editor-ai §1</a></td></tr></tbody></table><h3 id="wave-3-—-composites-depend-on-waves-1–2" tabindex="-1">Wave 3 — Composites (depend on Waves 1–2) <a class="header-anchor" href="#wave-3-—-composites-depend-on-waves-1–2" aria-label="Permalink to &quot;Wave 3 — Composites (depend on Waves 1–2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Refs anchor</th></tr></thead><tbody><tr><td><code>Panel</code></td><td><a href="./ui-revamp-v0">PRD §3</a> + <a href="./ui-revamp-v0-refs">refs main §2</a></td></tr><tr><td><code>PanelContainer</code></td><td>(composes <code>Panel</code>)</td></tr><tr><td><code>BotList</code></td><td><a href="./ui-revamp-v0-refs-assistant-bots">refs assistant-bots §3</a></td></tr><tr><td><code>CapabilityForm</code></td><td><a href="./ui-revamp-v0-refs">refs main §4</a> step 2</td></tr><tr><td><code>InlineAIAcceptBar</code></td><td><a href="./ui-revamp-v0-refs-editor-ai">refs editor-ai §4</a></td></tr><tr><td><code>InlineAIStream</code></td><td><a href="./ui-revamp-v0-refs-editor-ai">refs editor-ai §5</a></td></tr><tr><td><code>PopupShell</code> (refactor from <code>window-chrome</code>)</td><td><a href="./ui-revamp-v0-refs-popup-window">refs popup-window §2</a></td></tr></tbody></table><h3 id="wave-4-—-logic-glue" tabindex="-1">Wave 4 — Logic / glue <a class="header-anchor" href="#wave-4-—-logic-glue" aria-label="Permalink to &quot;Wave 4 — Logic / glue&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Refs anchor</th></tr></thead><tbody><tr><td><code>NodeAIRegistry</code> (TipTap integration)</td><td><a href="./ui-revamp-v0-refs-editor-ai">refs editor-ai §3</a>. The TipTap extension half of the registry — wires per-node-type AI action declarations into editor commands, owns context resolution (which node, which selection, which document). No UI. The <strong>interface</strong> for this lives in Wave 1 (see below) so Wave 2 components don&#39;t block on Wave 4.</td></tr></tbody></table><blockquote><p><strong>Note on the dependency inversion.</strong> Wave 2&#39;s <code>SlashMenu</code> and <code>SelectionAIBar</code> consume the registry. To avoid blocking those, the registry is split:</p><ul><li><strong>Wave 1 ships the interface</strong> — <code>editor/node-ai-registry.types.ts</code> declaring <code>NodeAIAction</code>, <code>NodeAIRegistry</code> (the type), and a trivial in-memory <code>createNodeAIRegistry()</code> implementation Wave 2 components can target and Storybook stories can mock.</li><li><strong>Wave 4 ships the TipTap integration</strong> — wires the registry into editor commands and node introspection. Wave 2 components don&#39;t change when this lands; they just receive a real registry instead of the in-memory one.</li></ul></blockquote><h2 id="_4-acceptance-criteria-—-when-is-a-component-done" tabindex="-1">4. Acceptance criteria — when is a component done? <a class="header-anchor" href="#_4-acceptance-criteria-—-when-is-a-component-done" aria-label="Permalink to &quot;4. Acceptance criteria — when is a component done?&quot;">​</a></h2><p>Before a <code>desktop/soma</code> screen wires a new (or refactored) component, the component must satisfy:</p><ol><li><strong>Storybook story exists</strong> at <code>src/stories/&lt;component&gt;.stories.tsx</code>. The story must cover, at minimum: default, hover, focus-visible, disabled, empty (if applicable), error (if applicable), and dark theme. For list rows / popovers also: keyboard navigation.</li><li><strong>No inline shadow utilities.</strong> Only <code>shadow-elevated</code> from the token sweep is permitted, and only on modal + popup classes.</li><li><strong><code>DensityProvider</code> aware.</strong> Reads density (even if v0 only emits <code>dense</code>) so post-v0 cozy is a switch, not a rewrite.</li><li><strong>Inline failure surfaces.</strong> Any primary action inside the component (form submit, dispatch, copy, etc.) renders failures inline. No <code>toast(...)</code> calls for these paths. (Cross-cutting ADR-0005 §6.)</li><li><strong>Keyboard-traversable</strong> if the component is a list, menu, or has multiple targets. Arrow keys + Enter; Esc closes.</li><li><strong>Color contrast ≥ AA at body size (<code>0.875rem</code> / 14px @ 16px root).</strong> Run <a href="../../../../desktop/desktop-ui/package.json"><code>pnpm --filter @soma/ui lint</code></a> and the existing visual-regression story snapshots; the Wave 0 Storybook contrast test-runner check is the regression gate.</li><li><strong>User-facing strings route through the i18n harness</strong> — no hardcoded English in JSX text or <code>aria-label</code>. Use the translation-key pattern established in Wave 0.</li><li><strong>Refs anchor cited in the component file&#39;s JSDoc header</strong>, so a future reader can find the lock pattern in one hop.</li></ol><p>Wave 4&#39;s <code>NodeAIRegistry</code> substitutes &quot;Storybook story&quot; with &quot;TipTap extension test exercising registration + action resolution for at least three node types&quot;.</p><h2 id="_5-cutover-order-into-desktop-soma" tabindex="-1">5. Cutover order into <code>desktop/soma</code> <a class="header-anchor" href="#_5-cutover-order-into-desktop-soma" aria-label="Permalink to &quot;5. Cutover order into `desktop/soma`&quot;">​</a></h2><p>Once a wave&#39;s components meet acceptance, the dependent <code>desktop/soma</code> screens swap from their existing implementation in a separate PR per screen — branch is the gate, no feature flag.</p><p>Screen-cutover sequence, ordered by v0 product priority (<a href="./ui-revamp-v0">PRD §7 step 6</a>):</p><ol><li><strong>Space settings shell + Bots tab</strong> (PRD §4.2 + §4.4). Requires <code>SettingsTabs</code>, <code>BotList</code>, <code>PeerAddressInput</code>, <code>CapabilityForm</code>, <code>Empty</code>, <code>DenseRow</code>, <code>Pill</code>, <code>DensityProvider</code>. → Waves 0, 1, 2, 3.</li><li><strong>Assistant tab</strong> (PRD §4.3). Adds <code>BackendSwitcher</code>&#39;s settings counterpart. → reuses Wave 2.</li><li><strong>Right area panel stack + chat panel</strong> (PRD §3, §4.5). Requires <code>Panel</code>, <code>PanelContainer</code>, <code>MentionPicker</code>, refactored chat composer with <code>BackendSwitcher</code> in footer.</li><li><strong>Editor surfaces</strong> — <code>SlashMenu</code>, <code>SelectionBubble</code>, <code>SelectionAIBar</code>, <code>InlineAIAcceptBar</code>, <code>InlineAIStream</code>, <code>NodeAIRegistry</code>. Requires Waves 2–4.</li><li><strong>Document column header</strong> — breadcrumb + <code>TreePopover</code>. → Wave 2.</li><li><strong>Spaces rail refactor</strong> (PRD §4.8). → Wave 1.</li><li><strong>Command palette wiring</strong> (cross-cutting). → Wave 2.</li><li><strong>Typing popup</strong> (PRD §4.7). Requires <code>PopupShell</code> + the existing <code>CharDisplay</code>. → Wave 3.</li></ol><p>This sequence keeps &quot;add a bot&quot; — the v0 product priority — at the front. The first end-user-visible improvement is space settings, not the editor revamp.</p><h2 id="_6-backend-items-that-must-land-in-parallel" tabindex="-1">6. Backend items that must land in parallel <a class="header-anchor" href="#_6-backend-items-that-must-land-in-parallel" aria-label="Permalink to &quot;6. Backend items that must land in parallel&quot;">​</a></h2><p>Several frontend cutovers depend on the embedded daemon (<a href="./../../../../backend/crates/daemon/"><code>backend/crates/daemon</code></a>, <a href="./../../../../backend/crates/agentd/"><code>backend/crates/agentd</code></a>, <a href="./../../../../backend/crates/soma-node/"><code>backend/crates/soma-node</code></a>) gaining new surface area:</p><ul><li><strong><code>list_space_bots</code></strong> on <code>SomaHandle</code> — required by space settings Bots tab (cutover 1).</li><li><strong>Bot handshake / capability issue / registration</strong> through the napi facade — required by <code>CapabilityForm</code>.</li><li><strong>Bot status stream</strong> over the existing event channel — required for live status pills.</li><li><strong>ACP backend management</strong> (add, mark default, validate) — required by Assistant tab (cutover 2).</li><li><strong>ACP chat completion + streaming</strong> to a per-space chat thread — required by chat panel (cutover 3).</li><li><strong><code>@bot:</code> dispatch routing</strong> — required by §4.6.</li><li><strong>Per-node AI action invocation</strong> routed through <code>soma-agentd</code> ACP — required by editor surfaces (cutover 4).</li></ul><p>These are tracked separately. The scaffold plan assumes the daemon team confirms what already exists vs. what needs new endpoints; gaps are filed as backend issues, not blockers to wave-0/1/2 UI work. UI work in waves 0–2 has no daemon dependency and can begin immediately.</p><h2 id="_7-out-of-scope-for-v0-scaffold" tabindex="-1">7. Out of scope for v0 scaffold <a class="header-anchor" href="#_7-out-of-scope-for-v0-scaffold" aria-label="Permalink to &quot;7. Out of scope for v0 scaffold&quot;">​</a></h2><ul><li>Cozy / oversized density variants. <code>DensityProvider</code> ships, but only emits dense.</li><li>Theme switcher UI. <code>cmyk</code> stays the default; <code>luxury</code> is exercised in Storybook for contrast testing only.</li><li><strong>Localized strings beyond English.</strong> Only English is shipped in v0 — but the <em>pattern</em> is established now. Wave 0 lands a thin i18n harness (translation keys + a single English catalog; <code>react-intl</code> or <code>i18next</code>&#39;s minimal config — decision deferred to the Wave 0 PR, just pick one and commit). Every new component in waves 1–3 routes user-facing strings through the harness. The cost is small per component and avoids a costly retrofit when the second locale lands.</li><li>Visual regression infrastructure beyond what already exists in Storybook.</li><li>Migration of every existing <code>desktop/soma</code> screen — only the screens listed in §5 are in v0.</li></ul><h2 id="_8-open-questions-for-the-lock-pass" tabindex="-1">8. Open questions for the lock pass <a class="header-anchor" href="#_8-open-questions-for-the-lock-pass" aria-label="Permalink to &quot;8. Open questions for the lock pass&quot;">​</a></h2><ol><li><strong><code>overlays/command-palette.tsx</code> refactor scope.</strong> Should the cross-cutting palette and the <code>TreePopover</code> (anchored under breadcrumbs) share an implementation, or are they two surfaces that look similar but diverge? Recommend: shared <code>Popover</code> + shared <code>RowList</code> primitives, but distinct top-level components — sections and scopes differ enough that one prop-set would balloon.</li><li><strong><code>Pill</code> API breadth.</strong> Two variant axes — semantic (<code>status</code> / <code>count</code> / <code>meta</code> / <code>default-marker</code>) and tone (<code>neutral</code> / <code>info</code> / <code>success</code> / <code>warn</code> / <code>error</code>). Lock the matrix before the component lands so consumers don&#39;t invent variants ad-hoc.</li><li><strong><code>PanelContainer</code> split gesture.</strong> Drag-to-split is in the PRD but has no clean refero analog. Keyboard fallback (<code>⌘\\\\</code> to split the focused panel) might be the safer v0 path with drag added in v0.1.</li><li><strong><code>InlineAIStream</code> and <code>ai-chat</code>&#39;s existing streaming code.</strong> Today&#39;s <a href="./../../../../desktop/desktop-ui/src/components/chat/ai-message.tsx"><code>chat/ai-message.tsx</code></a> presumably handles streaming inside the chat. Confirm whether the new <code>InlineAIStream</code> shares its <code>Thinking…</code> pill subcomponent with the chat (it should, per <a href="./ui-revamp-v0-refs-editor-ai">refs editor-ai §5</a>) or is built fresh.</li><li><strong>CharDisplay extraction work.</strong> Whether <code>tapia/char-display.tsx</code> needs any genuine change or just an audit. If just an audit, drop it from Wave 1 and treat it as already done.</li></ol><hr><p><em>Once this scaffold is locked, the next deliverable is Wave 0 — the token sweep PR — followed by Wave 1 component PRs in parallel.</em></p>',46)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
